CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS runs (id bigserial PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),grammar_version text NOT NULL,source_commit text,node_count int NOT NULL DEFAULT 0,edge_count int NOT NULL DEFAULT 0,admitted_count int NOT NULL DEFAULT 0,unmatched_count int NOT NULL DEFAULT 0,note text);
CREATE TABLE IF NOT EXISTS structures (id text PRIMARY KEY,kind text NOT NULL,dim int NOT NULL DEFAULT 0,recurrence_order int NOT NULL DEFAULT 0,symmetry text,sq int,anti boolean,multiplicity int NOT NULL DEFAULT 1,boundary_condition text,dual int NOT NULL DEFAULT 0,occupancy int,lifecycle text NOT NULL DEFAULT 'GENERABLE',verdict text NOT NULL DEFAULT 'UNMATCHED',paths int NOT NULL DEFAULT 1,depth int NOT NULL DEFAULT 0,label text,signature jsonb NOT NULL DEFAULT '{}'::jsonb,first_seen timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS edges (id bigserial PRIMARY KEY,source_id text NOT NULL REFERENCES structures(id) ON DELETE CASCADE,target_id text NOT NULL REFERENCES structures(id) ON DELETE CASCADE,operator text NOT NULL,paths int NOT NULL DEFAULT 1,UNIQUE(source_id,target_id,operator));
CREATE TABLE IF NOT EXISTS evidence (id bigserial PRIMARY KEY,structure_id text NOT NULL REFERENCES structures(id) ON DELETE CASCADE,status text NOT NULL,domain text,title text,claim text NOT NULL,source_url text,source_date date,caveat text,confidence real NOT NULL DEFAULT .5,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS discoveries (id bigserial PRIMARY KEY,structure_id text REFERENCES structures(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),event_type text NOT NULL,summary text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS proposals (id bigserial PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),proposal_type text NOT NULL,target text,rationale text NOT NULL,patch jsonb,status text NOT NULL DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS research_queue (id bigserial PRIMARY KEY,structure_id text NOT NULL REFERENCES structures(id) ON DELETE CASCADE,priority real NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'QUEUED',attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),UNIQUE(structure_id));
CREATE TABLE IF NOT EXISTS research_memory (id bigserial PRIMARY KEY,structure_id text REFERENCES structures(id) ON DELETE SET NULL,content text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,embedding vector(1536),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS research_memory_embedding_idx ON research_memory USING hnsw (embedding vector_cosine_ops);
